from pathlib import Path
import json,hashlib,zlib,base64,subprocess,sys
ROOT=Path(r'C:\Users\brand\OneDrive\Documents\dead-street')
GODOT=r'C:\Users\brand\OneDrive\Documents\Godot\Godot_v4.7.2-stable_win64_console.exe'
DATA=json.loads(zlib.decompress(base64.b64decode('')))
def git(*args):return subprocess.check_output(['git',*args],cwd=ROOT,text=True).strip()
assert git('rev-parse','HEAD')=='db92794c98981b4a12c45c4863c84480cfb7c1a7','HEAD changed'
assert git('branch','--show-current')=='build/arsenal-checkpoint-20260911','Branch changed'
assert not git('diff','--cached','--name-only'),'Existing staged work'
for n,v in DATA.items():
 p=ROOT/n;actual=hashlib.sha256(p.read_text(encoding='utf-8').encode()).hexdigest() if p.exists() else None
 assert actual==v['before'],str((n,'baseline changed',actual,v['before']))
for n,v in DATA.items():(ROOT/n).write_text(v['text'],encoding='utf-8',newline='\n')
print('FLEET_2034_APPLIED',len(DATA),flush=True)
logs=ROOT/'tools/vehicle_fleet/review_2034';logs.mkdir(exist_ok=True)
for script in ['build_catalog','build_art','build_guide','build_2034_boards']:
 subprocess.run([sys.executable,str(ROOT/'tools/vehicle_fleet'/f'{script}.py')],cwd=ROOT,check=True,timeout=900)
def run(name,args):
 with (logs/(name+'.log')).open('w',encoding='utf-8') as log:result=subprocess.run([GODOT,'--path',str(ROOT),*args],cwd=ROOT,stdout=log,stderr=subprocess.STDOUT,timeout=360)
 text=(logs/(name+'.log')).read_text(encoding='utf-8');print(name,'exit',result.returncode,text[-2200:],flush=True);assert result.returncode==0,name
run('import',['--headless','--editor','--quit'])
for name in ['compile_fleet','validate_fleet','validate_mixed','validate_panel']:run(name,['--headless','--script','tools/vehicle_fleet/'+name+'.gd'])
run('native',['--script','tools/vehicle_fleet/review_native.gd'])
for name in ['validation.json','validation_mixed.json','native_review/report.json']:assert not json.loads((ROOT/'tools/vehicle_fleet'/name).read_text())['errors'],name
(logs/'applied.json').write_text(json.dumps({'source_files':list(DATA),'head_before':git('rev-parse','HEAD'),'passed':True},indent=2))
print('FLEET_2034_NATIVE_TESTS_PASS',flush=True)
